<template><view v-if="customer" class="page"><view class="notice">演示数据，请勿录入真实顾客信息</view><view class="profile card"><view class="avatar">{{ customer.name.slice(0,1) }}</view><view><text class="name">{{ customer.name }}</text><text>{{ mask(customer.phone) }} · {{ customer.memberLevel }}</text><text>{{ customer.store }}</text></view></view><view class="section-title">基本资料</view><view class="card rows"><view><text>性别</text><b>{{ customer.gender || '未填写' }}</b></view><view><text>生日</text><b>{{ customer.birthday || '未填写' }}</b></view><view><text>顾客来源</text><b>{{ customer.source || '业务单同步' }}</b></view></view><view class="section-title">服务偏好与铺垫</view><view class="card rows"><view><text>特殊喜好</text><b>{{ customer.preferences || '暂无记录' }}</b></view><view><text>禁忌事项</text><b>{{ customer.taboos || '暂无记录' }}</b></view><view><text>铺垫内容</text><b>{{ customer.preparation || '暂无记录' }}</b></view><view><text>内部备注</text><b>{{ customer.note || '暂无记录' }}</b></view></view><view class="section-title">项目资产（只读）</view><view class="card rows"><view v-for="pkg in customer.packages" :key="pkg.project"><text>{{ pkg.project }}</text><b>剩余 {{ pkg.purchased-pkg.used }} 次 · {{ pkg.expiry }}</b></view><view><text>储值余额</text><b>¥{{ customer.balance }}</b></view><view><text>会员积分</text><b>{{ customer.points }}</b></view></view><view class="section-title">服务记录</view><view class="card records"><view v-for="record in records" :key="record.id"><b>{{ record.businessDate }} · {{ record.projects?.join('、') || record.estimatedProject }}</b><text>{{ stageLabel(record.status) }} · {{ record.diagnosisType }}</text></view></view><view class="section-title">影像与回访</view><view class="card records"><view v-for="image in customer.images" :key="`${image.type}${image.date}`"><b>{{ image.type }}影像 · {{ image.project }}</b><text>{{ image.date }}（演示资料，无实际文件）</text></view><view v-for="followup in customer.followups" :key="followup.id"><b>{{ followup.date }} · {{ followup.result }}</b><text>{{ followup.method }}：{{ followup.note || '无备注' }}</text></view><view v-if="!customer.images.length&&!customer.followups.length" class="muted">暂无影像或回访资料</view></view><text class="readonly-tip">本页资料和资产均为只读；请在个人待办中处理回访。</text></view></template>
<script setup>
import { ref } from 'vue'; import { onLoad } from '@dcloudio/uni-app'; import { customerRecords, getData, getSession, stages } from '../../services/repository'
const customer=ref(null),records=ref([]);onLoad(q=>{const employee=getSession();const data=getData();customer.value=data.customers.find(c=>c.id===q.id);if(!employee||!customer.value)return uni.reLaunch({url:'/pages/login/index'});records.value=customerRecords(q.id)});function mask(v){return v.replace(/^(\d{3})\d{4}(\d{4})$/, '$1****$2')}function stageLabel(v){return stages[v]?.label||v}
</script>
<style scoped>.profile{display:flex;align-items:center;padding:28rpx}.avatar{width:90rpx;height:90rpx;line-height:90rpx;border-radius:50%;background:#e9f1ff;color:#2167e8;text-align:center;font-size:35rpx;font-weight:700}.profile view:last-child{margin-left:20rpx}.profile text{display:block;margin-top:8rpx;color:#7b8494;font-size:24rpx}.profile .name{margin:0;color:#182033;font-size:34rpx;font-weight:700}.rows,.records{padding:0 22rpx}.rows view,.records view{padding:20rpx 0;border-bottom:1rpx solid #edf0f5}.rows view:last-child,.records view:last-child{border:0}.rows text{display:block;color:#7b8494;font-size:23rpx}.rows b{display:block;margin-top:8rpx;font-size:26rpx;font-weight:500}.records b,.records text{display:block;font-size:25rpx}.records text{margin-top:8rpx;color:#7b8494;font-size:23rpx}.readonly-tip{display:block;margin:28rpx 4rpx;color:#9a6700;font-size:23rpx}</style>
